// Fires on every subscriptions INSERT/UPDATE. Only a few transitions deserve an email.
const body = $('Webhook').first().json.body ?? {};
const config = $('Config').first().json;
const next = body.record ?? {};
const prev = body.old_record ?? {};
const names = { BASIC: 'Basic', PLUS: 'Plus', FAMILY: 'Family' };
const plan = names[next.plan] ?? next.plan ?? 'your plan';
const settingsUrl = String(config.siteUrl).replace(/\/+$/, '') + '/dashboard/settings';

let subject;
let text;

if (next.status === 'ACTIVE' && prev.status !== 'ACTIVE') {
  subject = 'Your FindIt subscription is active';
  text = `Hi,\n\nYour FindIt ${plan} subscription is active. You can manage it any time here:\n${settingsUrl}`;
} else if (next.status === 'PAST_DUE' && prev.status !== 'PAST_DUE') {
  subject = 'Action needed: your FindIt payment failed';
  text = `Hi,\n\nWe could not process your latest FindIt payment. Please update your payment method so your subscription stays active:\n${settingsUrl}`;
} else if (next.status === 'CANCELED' && prev.status !== 'CANCELED') {
  subject = 'Your FindIt subscription has ended';
  text = `Hi,\n\nYour FindIt subscription has ended. You can start a new one whenever you like:\n${settingsUrl}`;
} else if (next.status === 'ACTIVE' && next.cancel_at_period_end === true && prev.cancel_at_period_end !== true) {
  const ends = next.current_period_end ? new Date(next.current_period_end).toDateString() : 'the end of your billing period';
  subject = 'Your FindIt subscription will end soon';
  text = `Hi,\n\nYour FindIt subscription is set to end on ${ends}. If that was a mistake you can undo it here:\n${settingsUrl}`;
} else {
  return [];
}

return [{ json: { ownerId: next.owner_id, subject, text } }];
